head.script:
scwin.screenId = "uldmgt50100";

///////// 1. 변수 및 선언 영역 /////////

scwin.frame = undefined;


///////// 2. 초기화 영역 /////////

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_keyword", fn: function () { return String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("keyword"))); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = async function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.search();
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'uldmgt50100.onpageload' }); }
};

// [A] 초기 목록 미해결 — 진입 근거가 다른 액션을 가리킨다(element vs byformelement vs extractelement) — 어느 쪽인지 정할 근거가 없다


// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

scwin.form_listForm = { action: "", method: 'post', target: '' };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        await scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'uldmgt50100.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.form_2_onsubmit
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.form_2_onsubmit = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin form_2_onsubmit — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        return false
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'uldmgt50100.form_2_onsubmit' }); }
};

/**
 * @event
 * @name scwin.ipt_keyword_onkeyup
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.ipt_keyword_onkeyup = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin ipt_keyword_onkeyup — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.onEnter()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'uldmgt50100.ipt_keyword_onkeyup' }); }
};

/**
 * @event
 * @name scwin.img_112_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.img_112_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin img_112_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.search()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'uldmgt50100.img_112_onclick' }); }
};

/**
 * @event
 * @name scwin.img_124_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.img_124_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin img_124_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.excel()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'uldmgt50100.img_124_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_ShowExtractionStatus
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_ShowExtractionStatus = async function () {
    const sbmOptions = {
        id: "tx_fn_ShowExtractionStatus",
        method: "post",
        action: "/filing/byformElement.do",
        ref: "dma_ShowExtractionStatusReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "uldmgt50100.tx_fn_ShowExtractionStatus" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.tx_fn_ExtractItem
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_ExtractItem = async function () {
    const sbmOptions = {
        id: "tx_fn_ExtractItem",
        method: "post",
        action: "/filing/extractElement.do",
        ref: "dma_ExtractItemReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "uldmgt50100.tx_fn_ExtractItem" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.tx_fn_Excel
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_Excel = async function () {
    const sbmOptions = {
        id: "tx_fn_Excel",
        method: "post",
        action: "/filing/element.do",
        ref: "dma_ExcelReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "uldmgt50100.tx_fn_Excel" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.tx_fn_List_xhr
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_List_xhr = async function () {
    // ⛔주소가 없다 — as-is 는 «자기 자신» 에게 제출했는데(`self_submit`) 화면 자신의 액션 URL 을
    //   하나로 못 정했다(후보 0 또는 여럿). 빈 주소로 내보내면 «조용히 엉뚱한 곳» 이다.
    throw { bizMessage: "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_List_xhr", unresolved: "action:self_submit:tx_fn_List_xhr" };
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.list
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.list = async function () {
    /* sdd-asis-lifecycle:begin fn_List — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    scwin.form_listForm.action = "/filing/element.do";
    $c.util.getComponent('dma_ShowExtractionStatusReq').set('method', "findFormList");
    await scwin.tx_fn_List_xhr();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.onCompleteResponse
 * @author Inswave
 * @date 2026. 09. 29
 * @param responseText
 * @returns
 * @hidden N
*/
scwin.onCompleteResponse = function (responseText) {
    /* sdd-asis-lifecycle:begin onCompleteResponse — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    ($c.util.getComponent('formListDiv') && $c.util.getComponent('formListDiv').setValue) ? $c.util.getComponent('formListDiv').setValue(responseText) : (($c.util.getComponent('formListDiv') && $c.util.getComponent('formListDiv').setText) ? $c.util.getComponent('formListDiv').setText(responseText) : (console.warn('[sdd] 값 쓰기 미지원 컴포넌트: ' + 'formListDiv'), void (responseText)));
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.search
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.search = async function () {
    /* sdd-asis-lifecycle:begin fn_Search — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent('dma_ShowExtractionStatusReq').set('pageIndex', 1);
    await scwin.list();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.onEnter
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onEnter = async function () {
    /* sdd-asis-lifecycle:begin onEnter — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (event.keyCode == 13) {
        await scwin.search();
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.showExtractionStatus
 * @author Inswave
 * @date 2026. 09. 29
 * @param formCd formVer
 * @returns
 * @hidden N
*/
scwin.showExtractionStatus = async function (formCd, formVer) {
    /* sdd-asis-lifecycle:begin fn_ShowExtractionStatus — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent('dma_ShowExtractionStatusReq').set('formCd', formCd);
    $c.util.getComponent('dma_ShowExtractionStatusReq').set('formVer', formVer);
    $c.util.getComponent('dma_ShowExtractionStatusReq').set('method', "findByformElementStatus");
    scwin.form_listForm.target = "";
    scwin.form_listForm.action = "/filing/byformElement.do";
    await scwin.tx_fn_ShowExtractionStatus();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.extractItem
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.extractItem = async function () {
    /* sdd-asis-lifecycle:begin fn_ExtractItem — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let selected = false;
    if (document.listForm.extractTargets.length == null || document.listForm.extractTargets.length == 1) {
        selected = document.listForm.extractTargets.checked;
    } else {
        if (document.listForm.extractTargets.length > 1) {
            for (let i = 0; i < document.listForm.extractTargets.length; i++) {
                if (document.listForm.extractTargets[i].checked) {
                    selected = true;
                    break;
                }
            }
        }
    }
    if (!selected) {
        await $c.win.alert("선택된 서식이 없습니다.");
        return;
    }
    const _url = "about:blank";
    await $c.win.openPopup((function (__u) { var __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(_url), { id: "extractPop", popupName: "extractPop", width: "300", height: "400" }, {});
    $c.util.getComponent('dma_ShowExtractionStatusReq').set('method', "prepareExtractElement");
    scwin.form_listForm.action = "/filing/extractElement.do";
    scwin.form_listForm.target = "extractPop";
    await scwin.tx_fn_ExtractItem();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.viewAllFormList
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.viewAllFormList = function () {
    /* sdd-asis-lifecycle:begin viewAllFormList — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const allEditChecked = (document.listForm || { elements: [] }).allEdit.checked;
    let targetArr = new Array();
    if (document.listForm.extractTargets.length > 1) {
        targetArr = document.listForm.extractTargets;
    } else {
        targetArr[0] = document.listForm.extractTargets;
    }
    for (let i = 0; i < targetArr.length; i++) {
        if (targetArr[i].disabled === false) {
            targetArr[i].checked = allEditChecked;
        }
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.excel
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.excel = async function () {
    /* sdd-asis-lifecycle:begin fn_Excel — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    scwin.form_listForm.action = "/filing/element.do";
    $c.util.getComponent('dma_ShowExtractionStatusReq').set('method', "downloadFormList");
    scwin.form_listForm.target = "hiddenFrame";
    await scwin.tx_fn_Excel();
    /* sdd-asis-lifecycle:end */
};
